question_text:
다음 코드의 출력 결과는?

let a = 10;
let b = a;
a = 20;
console.log(b);

다음 코드의 출력 결과는?

let obj1 = { value: 10 };
let obj2 = obj1;
obj1.value = 20;
console.log(obj2.value);

다음 코드의 출력 결과는?

let x = 5;
console.log(++x);

다음 코드의 출력 결과는?

let x = 5;
console.log(x++);

다음 코드의 출력 결과는?

if (true) {
  let x = 10;
}
console.log(x);

다음 코드의 출력 결과는?

if (true) {
  var x = 10;
}
console.log(x);

다음 코드의 출력 결과는?

console.log(x);
var x = 10;

다음 코드의 출력 결과는?

console.log(x);
let x = 10;

다음 코드에서 에러가 발생하는 줄은?

const PI = 3.14;
PI = 3.14159;

다음 코드의 출력 결과는?

for (var i = 0; i < 3; i++) {}
console.log(i);

다음 코드의 출력 결과는?

for (let i = 0; i < 3; i++) {}
console.log(i);

다음 삼항 연산자의 결과는?

let result = (5 > 3) ? 'yes' : 'no';
console.log(result);

다음 코드의 출력 결과는?

for (let i = 0; i < 3; i++) {
  console.log(i);
}

다음 코드의 출력 결과는?

let arr = [10, 20, 30];
for (let value of arr) {
  console.log(value);
}

다음 코드의 출력 결과는?

let obj = {a: 1, b: 2};
for (let key in obj) {
  console.log(key);
}

다음 코드의 출력 결과는?

let x = 0;
while (x < 3) {
  x++;
}
console.log(x);

다음 코드의 출력 결과는?

if (0) {
  console.log('A');
} else {
  console.log('B');
}

다음 코드의 출력 결과는?

if ('hello') {
  console.log('A');
} else {
  console.log('B');
}

다음 코드의 출력 결과는?

function add(a = 5, b = 10) {
  return a + b;
}
console.log(add(3));

다음 코드의 출력 결과는?

const double = x => x * 2;
console.log(double(5));

다음 코드의 출력 결과는?

greet();
function greet() {
  console.log('Hello');
}

다음 코드의 출력 결과는?

greet();
const greet = function() {
  console.log('Hello');
};

다음 코드의 출력 결과는?

function sum(...numbers) {
  return numbers.reduce((a, b) => a + b, 0);
}
console.log(sum(1, 2, 3));

다음 코드의 출력 결과는?

const obj = { name: 'Alice', age: 30 };
console.log(obj.name);

다음 코드의 출력 결과는?

const obj = { name: 'Alice' };
console.log(obj['name']);

다음 코드의 출력 결과는?

const obj = {
  name: 'Alice',
  greet: function() {
    console.log(this.name);
  }
};
obj.greet();

다음 코드의 출력 결과는?

const obj = {
  name: 'Alice',
  greet: () => {
    console.log(this.name);
  }
};
obj.greet();

다음 코드와 동일한 것은?

const name = 'Alice';
const age = 30;
const obj = { name, age };

다음 코드의 출력 결과는?

const key = 'name';
const obj = { [key]: 'Alice' };
console.log(obj.name);

다음 코드의 출력 결과는?

const person = { name: 'Alice', age: 30 };
const { name, age } = person;
console.log(name);

다음 코드의 출력 결과는?

const arr = [1, 2, 3];
const [a, b] = arr;
console.log(a);

다음 코드의 출력 결과는?

const person = { name: 'Alice' };
const { name, age = 30 } = person;
console.log(age);

다음 코드의 출력 결과는?

const arr1 = [1, 2];
const arr2 = [...arr1, 3, 4];
console.log(arr2);

다음 코드의 출력 결과는?

const obj1 = { a: 1 };
const obj2 = { ...obj1, b: 2 };
console.log(obj2);

다음 코드의 출력 결과는?

const obj = { user: { name: 'Alice' } };
console.log(obj?.user?.name);

다음 코드의 출력 결과는?

const obj = { user: null };
console.log(obj?.user?.name);

다음 코드의 출력 결과는?

const obj = { name: 'Alice', age: 30 };
const json = JSON.stringify(obj);
console.log(typeof json);

다음 코드의 출력 결과는?

const arr = [1, 2, 3];
arr.forEach(num => console.log(num));

다음 코드의 출력 결과는?

const arr = [1, 2, 3];
const result = arr.map(num => num * 2);
console.log(result);

다음 코드의 출력 결과는?

const arr = [1, 2, 3, 4, 5];
const result = arr.filter(num => num > 3);
console.log(result);

다음 코드의 출력 결과는?

const arr = [1, 2, 3, 4, 5];
const result = arr.find(num => num > 3);
console.log(result);

다음 코드의 출력 결과는?

const arr = [1, 2, 3];
const result = arr.some(num => num > 2);
console.log(result);

다음 코드의 출력 결과는?

const arr = [1, 2, 3];
const result = arr.every(num => num > 0);
console.log(result);

다음 코드의 출력 결과는?

const arr = [1, 2, 3, 4];
const result = arr.reduce((acc, cur) => acc + cur, 0);
console.log(result);

다음 코드의 출력 결과는?

const arr = [1, 2, 3];
const result = arr.reduce((acc, cur) => acc * cur, 1);
console.log(result);

다음 코드의 출력 결과는?

class Person {
  constructor(name) {
    this.name = name;
  }
}
const p = new Person('Alice');
console.log(p.name);

다음 코드의 출력 결과는?

class Counter {
  constructor() {
    this.count = 0;
  }
  increment() {
    this.count++;
  }
}
const c = new Counter();
c.increment();
console.log(c.count);

다음 코드의 출력 결과는?

function greet() {
  console.log(this);
}
greet();

다음 코드에서 this가 가리키는 것은?

const obj = {
  name: 'Alice',
  greet() {
    console.log(this.name);
  }
};
obj.greet();

다음 코드의 출력 결과는?

const name = 'Alice';
const greeting = `Hello, ${name}!`;
console.log(greeting);

다음 코드의 출력 결과는?

const arr = [1, 2, 3];
const doubled = arr.map(x => x * 2).filter(x => x > 2);
console.log(doubled);

다음 코드의 출력 결과는?

const arr = [1, 2, 3, 4, 5];
const hasEven = arr.some(num => num % 2 === 0);
console.log(hasEven);

다음 코드의 출력 결과는?

const arr = [1, 3, 5, 7];
const allOdd = arr.every(num => num % 2 === 1);
console.log(allOdd);

다음 코드의 출력 결과는?

const obj = { a: 1, b: 2, c: 3 };
const { a, ...rest } = obj;
console.log(rest);

다음 코드의 출력 결과는?

const arr = [1, 2, 3];
const [first, ...rest] = arr;
console.log(rest);

다음 코드의 결과는?

const div = document.createElement('div');
div.textContent = 'Hello';
document.body.appendChild(div);

다음 코드의 결과는?

const div = document.querySelector('div');
div.style.color = 'red';

다음 코드의 실행 결과는?

const p = document.createElement('p');
p.textContent = 'Hello';
p.classList.add('greeting');
document.body.appendChild(p);

다음 코드의 실행 결과는?

const btn = document.querySelector('button');
btn.addEventListener('click', () => {
  console.log('Clicked!');
});

다음 코드에서 클릭 시 출력되는 것은?

const div = document.querySelector('div');
div.addEventListener('click', function(event) {
  console.log(event.target);
});

다음 코드는 이벤트 위임을 사용한 예시이다. 빈칸에 들어갈 것은?

ul.addEventListener('click', (e) => {
  if (e._____.tagName === 'LI') {
    console.log('리스트 클릭');
  }
});

다음 코드의 역할은?

form.addEventListener('submit', (e) => {
  e.preventDefault();
});

다음 코드에서 버튼 클릭 시 출력되는 값은?

const btn = document.querySelector('button');
btn.addEventListener('click', function() {
  console.log(this);
});

다음 코드에서 버튼 클릭 시 출력되는 값은?

const btn = document.querySelector('button');
btn.addEventListener('click', () => {
  console.log(this);
});

다음 코드의 실행 결과는?

const input = document.querySelector('input');
input.addEventListener('input', (e) => {
  console.log(e.target.value);
});
